def _rank(product: NormalizedProduct) -> int:
    return SOURCE_PRECEDENCE.index(product.source)


def _conflict_detail(kept: NormalizedProduct, dropped: NormalizedProduct) -> str | None:
    """Describe a field disagreement between two records of the same product."""
    if kept.price != dropped.price:
        return f"price {kept.price} ({kept.id}) vs {dropped.price} ({dropped.id})"
    return None


def deduplicate(
    products: Iterable[NormalizedProduct],
) -> tuple[list[NormalizedProduct], list[RunWarning]]:
    """Keep one record per identity, preferring SOURCE_PRECEDENCE; warn on disagreement.

    Precedence rather than arrival order keeps the result deterministic even though
    sources are fetched concurrently.
    """
    kept: dict[tuple[str, str], NormalizedProduct] = {}
    warnings: list[RunWarning] = []

    for product in products:
        key = identity_key(product)
        winner = kept.get(key)
        if winner is None:
            kept[key] = product
            continue

        loser = product if _rank(product) >= _rank(winner) else winner
        kept[key] = winner if loser is product else product
        detail = _conflict_detail(kept[key], loser)
        warnings.append(
            RunWarning(
                code=WarningCode.DUPLICATE_CONFLICT,
                source=loser.source,
                record_id=loser.id,
                detail=detail or f"duplicate of {kept[key].id}; identical values",
            )
        )

    return list(kept.values()), warnings

