            source=self._source,
            path=url,
            attempt=attempt + 1,
            delay_s=round(delay, 3),
            reason=_reason(exc),
        )
        await asyncio.sleep(delay)


def _reason(exc: BaseException) -> str:
    if isinstance(exc, httpx.HTTPStatusError):
        return f"HTTP {exc.response.status_code}"
    return type(exc).__name__


